  font-weight: 600;
  margin-top: 0.75rem;
  transition: all var(--transition);
}

.product-add-btn:hover,
.product-add-btn:focus-visible {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--bg-primary);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.product-add-btn svg {
  width: 16px;
  height: 16px;
}

/* =============================================
   DEALS SECTION
   ============================================= */
.deals-section {
  background: var(--bg-secondary);
}

.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 1.25rem;
}

.deal-card-featured {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1fr;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.deal-card-featured:hover {
  border-color: var(--border-accent);
  box-shadow: var(--shadow-elevated);
}

.deal-card-featured:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.deal-featured-img {
  position: relative;
  min-height: 320px;
  background: linear-gradient(135deg, #1e1e28 0%, #12121c 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
}

.deal-featured-content {
  padding: 2rem 1.5rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.75rem;
}

.deal-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  background: rgba(232, 93, 93, 0.15);
  border: 1px solid rgba(232, 93, 93, 0.3);
  color: var(--red);
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  width: fit-content;
}

.deal-title {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.3;
}

.deal-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.deal-price-block {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
}

.deal-price-new {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.deal-price-old {
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-muted);
  text-decoration: line-through;
}

.deal-discount-pct {
  background: var(--red);
  color: white;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.2rem 0.5rem;
  border-radius: var(--radius-sm);
}

.deal-countdown {
  display: flex;
  gap: 0.5rem;
  align-items: center;
}

.deal-countdown-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  font-weight: 500;
}

.countdown-unit {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0.25rem 0.5rem;
  text-align: center;
  min-width: 38px;
}

.countdown-num {
  font-size: 1rem;
  font-weight: 700;
  color: var(--accent);
  display: block;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}

.countdown-seg {
  font-size: 0.55rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.deal-mini-list {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.deal-mini-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 1rem;
  display: flex;
  gap: 1rem;
  align-items: center;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.deal-mini-card:hover {
  border-color: var(--border-accent);
  box-shadow: var(--shadow-card);
}

.deal-mini-card:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.deal-mini-img {
  width: 72px;
  height: 72px;
  border-radius: var(--radius-sm);
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  flex-shrink: 0;
}

.deal-mini-content {
  flex: 1;
  min-width: 0;
}

.deal-mini-title {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.deal-mini-title a:hover,
.deal-mini-title a:focus-visible {
  color: var(--accent);
  outline: none;
  text-decoration: underline;
}

.deal-mini-price-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.deal-mini-price {
  font-size: 1rem;
  font-weight: 700;
}

.deal-mini-original {
  font-size: 0.8125rem;
  color: var(--text-muted);
  text-decoration: line-through;
}

.deal-mini-save {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--green);
}

.deal-mini-progress {
  margin-top: 0.5rem;
}

.progress-label {
  display: flex;
  justify-content: space-between;
  font-size: 0.6875rem;
  color: var(--text-muted);
  margin-bottom: 0.25rem;
}

.progress-bar {
  height: 4px;
  background: var(--bg-elevated);
  border-radius: 9999px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--accent-dim));
  border-radius: 9999px;
  transition: width 1s ease;
}

/* =============================================
   EDITORIAL / LOOKBOOK
   ============================================= */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.25rem;
}

.editorial-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition), border-color var(--transition), box-shadow var(--transition);
}

.editorial-card:hover {
  transform: translateY(-3px);
  border-color: var(--border-accent);
  box-shadow: var(--shadow-elevated);
}

.editorial-card:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.editorial-card--large {
  grid-column: 1 / 2;
  grid-row: 1 / 3;
}

.editorial-img {
  position: relative;
  overflow: hidden;
}

.editorial-card--large .editorial-img {
  aspect-ratio: 3 / 4;
}

.editorial-card:not(.editorial-card--large) .editorial-img {
  aspect-ratio: 16 / 9;
}

.editorial-img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  min-height: 160px;
}

.editorial-img-placeholder--a {
  background: linear-gradient(135deg, #1c1822 0%, #0e0c14 100%);
}

.editorial-img-placeholder--b {
  background: linear-gradient(135deg, #0e1c18 0%, #0a1210 100%);
}

.editorial-img-placeholder--c {
  background: linear-gradient(135deg, #1c1410 0%, #110d0a 100%);
}

.editorial-img-placeholder--d {
  background: linear-gradient(135deg, #101824 0%, #0a0e18 100%);
}

.editorial-img-placeholder--e {
  background: linear-gradient(135deg, #1a1012 0%, #110a0c 100%);
}

.editorial-content {
  padding: 1.25rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.editorial-category {
  font-size: 0.6875rem;
  font-weight: 700;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.editorial-title {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: -0.01em;
}

.editorial-card--large .editorial-title {
  font-size: 1.25rem;
}

.editorial-title a:hover,
.editorial-title a:focus-visible {
  color: var(--accent);
  outline: none;
  text-decoration: underline;
}

.editorial-excerpt {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.editorial-card--large .editorial-excerpt {
  -webkit-line-clamp: 4;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: auto;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border);
}

.editorial-author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  flex-shrink: 0;
  overflow: hidden;
}

.editorial-author-name {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.editorial-date {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-left: auto;
}

/* =============================================
   BRAND STRIP
   ============================================= */
.brands-strip {
  padding: 2.5rem 1.5rem;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  background: var(--bg-secondary);
}

.brands-strip-inner {
  max-width: 1280px;
  margin: 0 auto;
}

.brands-label {
  text-align: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  margin-bottom: 1.5rem;
}

.brands-logos {
  display: flex;
  gap: 1.5rem;
  justify-content: center;
  flex-wrap: wrap;
  align-items: center;
}

.brand-logo {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0.75rem 1.5rem;
  font-size: 0.875rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  text-transform: uppercase;
  transition: all var(--transition);
  cursor: default;
}

.brand-logo:hover {
  color: var(--text-primary);
  border-color: var(--border-accent);
  background: var(--accent-glow);
}

/* =============================================
   NEWSLETTER
   ============================================= */
.newsletter-section {
  padding: 4rem 1.5rem;
  background: var(--bg-primary);
}

.newsletter-inner {
  max-width: 680px;
  margin: 0 auto;
  text-align: center;
}

.newsletter-icon {
  width: 56px;
  height: 56px;
  background: var(--accent-glow);
  border: 1px solid var(--border-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
  font-size: 1.75rem;
}

.newsletter-title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -0.025em;
  margin-bottom: 0.75rem;
}

.newsletter-desc {
  font-size: 1rem;
  color: var(--text-secondary);
  margin-bottom: 2rem;
  line-height: 1.6;
}

.newsletter-form {
  display: flex;
  gap: 0.625rem;
  max-width: 480px;
  margin: 0 auto;
}

.newsletter-input {
  flex: 1;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0.75rem 1rem;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 0.9375rem;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.newsletter-input::placeholder {
  color: var(--text-muted);
}

.newsletter-input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

.newsletter-submit {
  background: var(--accent);
  color: var(--bg-primary);
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius-sm);
  font-size: 0.9375rem;
  font-weight: 700;
  border: none;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition);
  white-space: nowrap;
}

.newsletter-submit:hover,
.newsletter-submit:focus-visible {
  background: var(--accent-dim);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.newsletter-note {
  margin-top: 1rem;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.newsletter-success {
  display: none;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--green);
  padding: 0.75rem;
}

/* =============================================
   FOOTER
   ============================================= */
.site-footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 3rem 1.5rem 1.5rem;
}

.footer-inner {
  max-width: 1280px;
  margin: 0 auto;
}

.footer-top {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 2.5rem;
  margin-bottom: 2.5rem;
}

.footer-brand-logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.875rem;
}

.footer-brand-name {
  font-size: 1.0625rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.footer-brand-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  max-width: 280px;
  margin-bottom: 1.25rem;
}

.footer-social {
  display: flex;
  gap: 0.5rem;
}

.footer-social-link {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  font-size: 0.875rem;
  transition: all var(--transition);
}

.footer-social-link:hover,
.footer-social-link:focus-visible {
  color: var(--text-primary);
  border-color: var(--border-accent);
  background: var(--accent-glow);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.footer-col-title {
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-primary);
  margin-bottom: 1rem;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.footer-links a {
  font-size: 0.875rem;
  color: var(--text-secondary);
  transition: color var(--transition);
}

.footer-links a:hover,
.footer-links a:focus-visible {
  color: var(--accent);
  outline: none;
  text-decoration: underline;
}

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.footer-copy {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.footer-legal {
  display: flex;
  gap: 1.25rem;
}

.footer-legal a {
  font-size: 0.8125rem;
  color: var(--text-muted);
  transition: color var(--transition);
}

.footer-legal a:hover,
.footer-legal a:focus-visible {
  color: var(--text-secondary);
  outline: none;
  text-decoration: underline;
}

.footer-payment-icons {
  display: flex;
  gap: 0.375rem;
  align-items: center;
}

.payment-icon {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 2px 6px;
  font-size: 0.6875rem;
  font-weight: 700;
  color: var(--text-muted);
}

/* =============================================
   TOAST NOTIFICATION
   ============================================= */
.toast-container {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  pointer-events: none;
}

.toast {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 0.875rem 1.25rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  box-shadow: var(--shadow-elevated);
  transform: translateX(120%);
  transition: transform 0.3s ease, opacity 0.3s ease;
  opacity: 0;
  pointer-events: all;
  max-width: 320px;
  min-width: 240px;
}

.toast.show {
  transform: translateX(0);
  opacity: 1;
}

.toast-icon {
  font-size: 1.25rem;
  flex-shrink: 0;
}

.toast-text {
  font-size: 0.875rem;
  font-weight: 500;
  flex: 1;
}

.toast-close {
  color: var(--text-muted);
  font-size: 1rem;
  line-height: 1;
  flex-shrink: 0;
  transition: color var(--transition);
}

.toast-close:hover {
  color: var(--text-primary);
}

/* =============================================
   RESPONSIVE
   ============================================= */
@media (max-width: 1024px) {
  .deals-grid {
    grid-template-columns: 1fr;
  }

  .deal-card-featured {
    grid-template-columns: 1fr 1fr;
  }

  .editorial-grid {
    grid-template-columns: 1fr 1fr;
  }

  .editorial-card--large {
    grid-column: 1 / 3;
    grid-row: auto;
  }

  .editorial-card--large .editorial-img {
    aspect-ratio: 16 / 7;
  }

  .footer-top {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links,
  .nav-cta {
    display: none;
  }

  .nav-mobile-toggle {
    display: flex;
  }

  .hero-inner {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-desc {
    margin-left: auto;
    margin-right: auto;
  }

  .hero-actions {
    justify-content: center;
  }

  .hero-stats {
    justify-content: center;
  }

  .hero-visual {
    display: none;
  }

  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .deal-card-featured {
    grid-template-columns: 1fr;
  }

  .deal-featured-img {
    min-height: 200px;
  }

  .editorial-grid {
    grid-template-columns: 1fr;
  }

  .editorial-card--large {
    grid-column: auto;
  }

  .footer-top {
    grid-template-columns: 1fr 1fr;
    gap: 1.5rem;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .newsletter-form {
    flex-direction: column;
  }
}

@media (max-width: 480px) {
  .section {
    padding: 2.5rem 1rem;
  }

  .hero-inner {
    padding: 2.5rem 1rem;
  }

  .products-grid {
    grid-template-columns: 1fr;
  }

  .hero-stats {
    gap: 1.25rem;
  }

  .footer-top {
    grid-template-columns: 1fr;
  }
}

/* =============================================
   MOBILE NAV DRAWER
   ============================================= */
.mobile-nav {
  position: fixed;
  inset: 0;
  z-index: 200;
  pointer-events: none;
}

.mobile-nav-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.7);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.mobile-nav-drawer {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(320px, 85vw);
  background: var(--bg-secondary);
  border-left: 1px solid var(--border);
  transform: translateX(100%);
  transition: transform 0.3s ease;
  display: flex;
  flex-direction: column;
  padding: 1.5rem;
  gap: 0.5rem;
  overflow-y: auto;
}

.mobile-nav.open {
  pointer-events: all;
}

.mobile-nav.open .mobile-nav-backdrop {
  opacity: 1;
}

.mobile-nav.open .mobile-nav-drawer {
  transform: translateX(0);
}

.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 0.5rem;
}

.mobile-nav-close {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: all var(--transition);
}

.mobile-nav-close:hover,
.mobile-nav-close:focus-visible {
  color: var(--text-primary);
  background: var(--bg-elevated);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.mobile-nav-link {
  display: block;
  padding: 0.75rem 0.875rem;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-secondary);
  transition: all var(--transition);
}

.mobile-nav-link:hover,
.mobile-nav-link:focus-visible {
  color: var(--text-primary);
  background: var(--bg-elevated);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* =============================================
   FOCUS VISIBLE GLOBAL
   ============================================= */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

:focus:not(:focus-visible) {
  outline: none;
}

/* =============================================
