  'use strict';

  /* ---- Cart state ---- */
  let cartCount = 0;

  function updateCartBadge() {
    const badge = document.getElementById('cart-badge');
    if (!badge) return;
    badge.textContent = cartCount;
    badge.hidden = cartCount === 0;
    const btn = badge.closest('button');
    if (btn) btn.setAttribute('aria-label', `Cart, ${cartCount} item${cartCount !== 1 ? 's' : ''}`);
  }

  /* ---- Toast notifications ---- */
  function showToast(message, icon = '✅') {
    const container = document.getElementById('toast-container');
    if (!container) return;

    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.setAttribute('role', 'status');
    toast.setAttribute('aria-live', 'polite');
    toast.innerHTML = `
      <span class="toast-icon" aria-hidden="true">${icon}</span>
      <span class="toast-text">${message}</span>
      <button class="toast-close" aria-label="Dismiss notification">✕</button>
    `;

    container.appendChild(toast);
    requestAnimationFrame(() => {
      requestAnimationFrame(() => toast.classList.add('show'));
    });

    const dismiss = () => {
      toast.classList.remove('show');
      toast.addEventListener('transitionend', () => toast.remove(), { once: true });
    };

    toast.querySelector('.toast-close').addEventListener('click', dismiss);
    setTimeout(dismiss, 3500);
  }

  /* ---- Add to cart ---- */
  function handleAddToCart(e) {
    const btn = e.target.closest('.product-add-btn, [data-add-to-cart]');
    if (!btn) return;

    const card = btn.closest('[data-product-name]');
    const name = card ? card.dataset.productName : 'Item';

    cartCount++;
    updateCartBadge();
    showToast(`<strong>${name}</strong> added to cart`, '🛒');

