    setTimeout(() => {
      btn.innerHTML = `<svg aria-hidden="true" viewBox="0 0 20 20" fill="currentColor"><path d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2 4m12-4l2 4M9 19a1 1 0 100-2 1 1 0 000 2zm8 0a1 1 0 100-2 1 1 0 000 2z"/></svg>Add to Cart`;
      btn.disabled = false;
      btn.removeAttribute('aria-disabled');
    }, 2000);
  }

  /* ---- Wishlist toggle ---- */
  function handleWishlist(e) {
    const btn = e.target.closest('.product-wishlist');
    if (!btn) return;

    const pressed = btn.getAttribute('aria-pressed') === 'true';
    btn.setAttribute('aria-pressed', String(!pressed));

    const card = btn.closest('[data-product-name]');
    const name = card ? card.dataset.productName : 'Item';

    if (!pressed) {
      btn.innerHTML = `<svg aria-hidden="true" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M3.172 5.172a4 4 0 015.656 0L10 6.343l1.172-1.171a4 4 0 115.656 5.656L10 17.657l-6.828-6.829a4 4 0 010-5.656z" clip-rule="evenodd"/></svg>`;
      showToast(`<strong>${name}</strong> saved to wishlist`, '♥');
    } else {
      btn.innerHTML = `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20.84 4.61a5.5 5.5 0 00-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 00-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 000-7.78z"/></svg>`;
    }
  }

  /* ---- Category filter pills ---- */
  function handleCategoryPill(e) {
    const pill = e.target.closest('.category-pill');
    if (!pill) return;

    const pills = document.querySelectorAll('.category-pill');
    pills.forEach(p => p.setAttribute('aria-pressed', 'false'));
    pill.setAttribute('aria-pressed', 'true');
  }

  /* ---- Deal countdown timer ---- */
  function initCountdown() {
    const end = new Date(Date.now() + 8 * 3600 * 1000 + 23 * 60 * 1000 + 47 * 1000);

    function tick() {
      const diff = Math.max(0, end - Date.now());
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);

      const pad = n => String(n).padStart(2, '0');

      const hEl = document.getElementById('cd-hours');
      const mEl = document.getElementById('cd-minutes');
      const sEl = document.getElementById('cd-seconds');

      if (hEl) hEl.textContent = pad(h);
      if (mEl) mEl.textContent = pad(m);
      if (sEl) sEl.textContent = pad(s);

      // Update accessible label
      const region = document.getElementById('countdown-region');
      if (region) {
        region.setAttribute('aria-label', `Deal ends in ${pad(h)} hours ${pad(m)} minutes ${pad(s)} seconds`);
      }
    }

    tick();
    setInterval(tick, 1000);
  }

  /* ---- Progress bars animation ---- */
  function animateProgressBars() {
    const bars = document.querySelectorAll('.progress-fill[data-width]');
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const bar = entry.target;
          bar.style.width = bar.dataset.width;
          observer.unobserve(bar);
        }
      });
    }, { threshold: 0.3 });

    bars.forEach(bar => {
      bar.style.width = '0%';
      observer.observe(bar);
    });
  }

  /* ---- Mobile nav ---- */
  function initMobileNav() {
    const toggle = document.getElementById('mobile-nav-toggle');
    const nav = document.getElementById('mobile-nav');
    const close = document.getElementById('mobile-nav-close');
    const backdrop = nav?.querySelector('.mobile-nav-backdrop');

    if (!toggle || !nav) return;

    function openNav() {
      nav.classList.add('open');
      toggle.setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden';
      close?.focus();
    }

    function closeNav() {
      nav.classList.remove('open');
      toggle.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
      toggle.focus();
    }

    toggle.addEventListener('click', openNav);
    close?.addEventListener('click', closeNav);
    backdrop?.addEventListener('click', closeNav);

    nav.addEventListener('keydown', e => {
      if (e.key === 'Escape') closeNav();
    });
  }

  /* ---- Newsletter form ---- */
  function initNewsletter() {
    const form = document.getElementById('newsletter-form');
    if (!form) return;

    form.addEventListener('submit', e => {
      e.preventDefault();
      const input = form.querySelector('.newsletter-input');
      const submitBtn = form.querySelector('.newsletter-submit');
      const success = document.getElementById('newsletter-success');

      if (!input?.value.trim()) {
        input?.focus();
        return;
      }

      if (submitBtn) submitBtn.disabled = true;

      setTimeout(() => {
        form.style.display = 'none';
        if (success) {
          success.style.display = 'flex';
          success.focus();
        }
        showToast('You\'re on the list! 🎉', '📬');
      }, 600);
    });
  }

  /* ---- Search interaction ---- */
  function initSearch() {
    const btn = document.getElementById('search-btn');
    if (!btn) return;

    btn.addEventListener('click', () => {
      showToast('Search coming soon!', '🔍');
    });
  }

  /* ---- Init ---- */
  document.addEventListener('DOMContentLoaded', () => {
    updateCartBadge();
    initCountdown();
    animateProgressBars();
    initMobileNav();
    initNewsletter();
    initSearch();

    document.body.addEventListener('click', handleAddToCart);
    document.body.addEventListener('click', handleWishlist);
    document.body.addEventListener('click', handleCategoryPill);
  });
})();
